package com.yihe.framework.ehr;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.core.io.ClassPathResource;import org.springframework.util.StreamUtils;
import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
@Service @SuppressWarnings("unchecked") public class QuestionnaireWorkflow {
 final EhrRepository db;final EhrService ehr;final QuestionnaireService surveys;
 public QuestionnaireWorkflow(EhrRepository db,EhrService ehr,QuestionnaireService surveys){this.db=db;this.ehr=ehr;this.surveys=surveys;}
 Map<String,Object> obj(Object o){return o instanceof Map?(Map<String,Object>)o:new LinkedHashMap<>();}
 List<Map<String,Object>> list(Object o){return QuestionnaireScoring.rows(o);}
 Map<String,Object> catalog(){try{return obj(ehr.decode(StreamUtils.copyToString(new ClassPathResource("questionnaire-catalog.json").getInputStream(),StandardCharsets.UTF_8)));}catch(java.io.IOException e){throw new IllegalStateException(e);}}
 Map<String,Object> state(EhrActor a,boolean lock){Map<String,Object> row=db.one("SELECT * FROM a_questionnaire_center_state WHERE scope_code=? AND data_mode=?"+(lock?" FOR UPDATE":""),a.scope,a.mode);require(row!=null,409,"请先初始化问卷资料库");return row;}
 @Transactional public Object bootstrap(EhrActor a){surveys.doctor(a);db.exec("INSERT IGNORE INTO a_questionnaire_center_state(scope_code,data_mode,document_json,updated_by,updated_at) VALUES(?,?,?,?,UTC_TIMESTAMP(6))",a.scope,a.mode,ehr.encode(catalog()),a.user);for(int i=0;i<2;i++){String key=UUID.nameUUIDFromBytes(bytes(a.scope+":"+a.mode+":questionnaire-template-v1:"+i)).toString();if(db.count("SELECT COUNT(*) FROM a_questionnaires WHERE questionnaire_id=?",key)>0)continue;String title=i==0?"职工情绪与焦虑筛查（待配置发布）":"煤矿工作适应与支持需求调查（自编）";List<String> selected=i==0?Arrays.asList("PHQ-9","GAD-7"):Arrays.asList("MINE-WELLBEING");String start=LocalDateTime.now(ZoneId.of("Asia/Shanghai")).plusHours(1).withSecond(0).withNano(0).toString(),end=LocalDateTime.now(ZoneId.of("Asia/Shanghai")).plusDays(14).withSecond(0).withNano(0).toString();Map<String,Object>p=map("id",key,"name",title,"scales",selected,"scale",String.join("、",selected),"audience","全体在职员工","time",start,"endTime",end,"answerChannel","h5","aiEnabled",true,"randomize",false,"notes","模板草稿，尚未发放；发布前核对目的、对象与时间。","wizard",map("settings",map("scoreMode","standard","aiReport",true,"alerts",true,"intervention",true,"feedback",Arrays.asList("employee","manager","doctor")),"release",map("range","all","channels",Arrays.asList("system"),"time",start,"endTime",end,"reminder",true,"interval",3,"maxReminders",3,"access",Arrays.asList("employee","doctor"),"openAfter","review")));db.insert("a_questionnaires",map("questionnaire_id",key,"scope_code",a.scope,"data_mode",a.mode,"title",title,"category","psychological","audience","全体在职员工","document_json",ehr.encode(build(a,p,catalog(),false)),"created_by",a.user,"updated_by",a.user,"created_at",now(),"updated_at",now()));}return workspace(a);}
 public Map<String,Object> workspace(EhrActor a){surveys.doctor(a);Map<String,Object> row=state(a,false),out=obj(ehr.decode(row.get("document_json")));out.put("version",row.get("row_version"));List<Object> plans=new ArrayList<>(),answers=new ArrayList<>(),histories=new ArrayList<>();
  for(Map<String,Object> q:db.all("SELECT * FROM a_questionnaires WHERE scope_code=? AND data_mode=? AND questionnaire_status<>'deleted' ORDER BY created_at",a.scope,a.mode)){Map<String,Object> doc=obj(ehr.decode(q.get("document_json"))),ui=new LinkedHashMap<>(obj(doc.get("centerConfig")));ui.putAll(map("id",q.get("questionnaire_id"),"name",q.get("title"),"version",q.get("row_version"),"status","draft".equals(q.get("questionnaire_status"))?"草稿":"active".equals(q.get("questionnaire_status"))?"进行中":"已完成","time",ui.getOrDefault("time",str(q.get("created_at")).replace(' ','T')),"createdAt",q.get("created_at"),"updatedAt",q.get("updated_at")));ui.putIfAbsent("scale",doc.getOrDefault("scaleId","自定义"));ui.putIfAbsent("scales",Collections.emptyList());ui.put("people",db.count("SELECT COUNT(*) FROM a_questionnaire_assignments x JOIN a_questionnaire_releases l ON l.release_id=x.release_id WHERE l.questionnaire_id=?",q.get("questionnaire_id")));ui.put("questionCount",list(doc.get("questions")).size());ui.put("submitted",db.count("SELECT COUNT(*) FROM a_questionnaire_responses s JOIN a_questionnaire_assignments x ON x.assignment_id=s.assignment_id JOIN a_questionnaire_releases l ON l.release_id=x.release_id WHERE l.questionnaire_id=?",q.get("questionnaire_id")));plans.add(ui);}
  String join=" FROM a_questionnaire_responses s JOIN a_questionnaire_assignments x ON x.assignment_id=s.assignment_id AND x.scope_code=s.scope_code AND x.data_mode=s.data_mode JOIN a_questionnaire_releases l ON l.release_id=x.release_id JOIN a_health_records r ON r.record_id=x.record_id AND r.scope_code=x.scope_code AND r.data_mode=x.data_mode JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode LEFT JOIN a_questionnaire_processing f ON f.response_id=s.response_id WHERE s.scope_code=? AND s.data_mode=? AND p.deleted_at IS NULL";
  for(Map<String,Object> r:db.all("SELECT s.*,x.record_id,l.release_id,l.questionnaire_id,l.document_json document,p.employee_name,p.employee_no,p.organization_name,f.score_json,f.ai_state,f.ai_output,f.ai_error,f.alert_state,f.intervention_json,f.archived,f.row_version processingVersion"+join+" ORDER BY s.submitted_at DESC",a.scope,a.mode)){Map<String,Object> doc=obj(ehr.decode(r.get("document"))),score=obj(ehr.decode(r.get("score_json")));boolean anonymous=Boolean.TRUE.equals(obj(doc.get("centerConfig")).get("anonymous"));String risk="confirmed".equals(r.get("review_state"))?str(r.get("risk_level")):str(score.getOrDefault("risk","unknown"));Map<String,Object> item=map("id",r.get("response_id"),"name",anonymous?"匿名答卷":r.get("employee_name"),"code",anonymous?"—":r.get("employee_no"),"unit",anonymous?"匿名":r.get("organization_name"),"recordId",anonymous?null:r.get("record_id"),"releaseId",r.get("release_id"),"plan",r.get("questionnaire_id"),"scale",String.join("、",names(list(score.get("scales")))),"score",r.get("total_score"),"aiRisk",riskLabel(str(score.getOrDefault("risk","unknown"))),"risk",riskLabel(risk),"review","confirmed".equals(r.get("review_state"))?"已审核":"rejected".equals(r.get("review_state"))?"已退回":"待审核","ai",aiLabel(str(r.get("ai_state"))),"aiOutput",r.get("ai_output"),"aiError",r.get("ai_error"),"time",r.get("submitted_at"),"note",r.get("review_note"),"version",r.get("row_version"),"processingVersion",r.get("processingVersion"),"alertState",r.get("alert_state"),"task",r.get("intervention_json")==null?"":ehr.decode(r.get("intervention_json")),"demoItems",score.getOrDefault("items",Collections.emptyList()),"scoring",score,"archived",num(r.get("archived"))==1,"anonymous",anonymous);answers.add(item);}
  for(Map<String,Object> h:db.all("SELECT l.release_id id,l.questionnaire_id,l.document_json document,l.published_at,l.release_status,COUNT(x.assignment_id) participants,COUNT(s.response_id) completed,AVG(s.total_score) average,SUM(s.review_state='confirmed' AND s.risk_level IN ('high','critical')) high,SUM(s.review_state='confirmed' AND s.risk_level='medium') medium,SUM(s.review_state='confirmed' AND s.risk_level='low') low FROM a_questionnaire_releases l LEFT JOIN a_questionnaire_assignments x ON x.release_id=l.release_id LEFT JOIN a_questionnaire_responses s ON s.assignment_id=x.assignment_id WHERE l.scope_code=? AND l.data_mode=? GROUP BY l.release_id,l.questionnaire_id,l.document_json,l.published_at,l.release_status ORDER BY l.published_at DESC",a.scope,a.mode)){Map<String,Object>d=obj(ehr.decode(h.remove("document"))),c=obj(d.get("centerConfig"));h.put("average",list(d.get("scoringScales")).size()>1?null:h.get("average"));h.putAll(map("name",d.get("title"),"scale",c.getOrDefault("scale","自定义"),"date",str(h.get("published_at")).substring(0,10),"status","archived".equals(h.get("release_status"))?"已归档":"进行中","sampleAnswerIds",new ArrayList<>(),"mode","database"));for(Object o:answers){Map<String,Object>v=obj(o);if(Objects.equals(v.get("releaseId"),h.get("id")))((List<Object>)h.get("sampleAnswerIds")).add(v.get("id"));}histories.add(h);}
  out.putAll(map("plans",plans,"answers",answers,"historyPlans",histories,"notes","","answerViewVersion",2,"mode","database","recipients",db.all("SELECT r.record_id id,p.employee_name name,p.employee_no code,p.organization_name unit,p.team_name team,p.position_name job"+ehr.baseSql(),a.scope,a.mode),"assigned",db.count("SELECT COUNT(*) FROM a_questionnaire_assignments WHERE scope_code=? AND data_mode=?",a.scope,a.mode)));return out;
 }
 static List<String> names(List<Map<String,Object>> rows){List<String> n=new ArrayList<>();for(Map<String,Object>r:rows)n.add(str(r.get("name")));return n;}
 static String riskLabel(String l){return "low".equals(l)?"正常":"mild".equals(l)?"轻度风险":"medium".equals(l)?"中度风险":"high".equals(l)?"高风险":"critical".equals(l)?"极高风险":"未分级";}
 static String aiLabel(String l){return "completed".equals(l)?"已完成":"failed".equals(l)?"失败":"disabled".equals(l)?"未启用":"running".equals(l)?"分析中":"待分析";}
 @Transactional public Object save(EhrActor a,Map<String,Object>b){surveys.doctor(a);Map<String,Object> receipt=surveys.receipt(a,"center-save",b);if(receipt.get("result_json")!=null)return ehr.decode(receipt.get("result_json"));Map<String,Object> old=state(a,true);require(num(b.get("version"))==num(old.get("row_version")),409,"其他人员已更新资料，请刷新后重新编辑");Map<String,Object> incoming=obj(b.get("document"));require(ehr.encode(incoming).length()<1500000,422,"配置内容过大");Map<String,Object> protectedCatalog=catalog();Map<String,Map<String,Object>> originals=new HashMap<>();for(String kind:Arrays.asList("scales","questions"))for(Map<String,Object> v:list(protectedCatalog.get(kind)))originals.put(kind+":"+v.get("id"),v);
  Map<String,Object> clean=new LinkedHashMap<>();for(String kind:Arrays.asList("scales","questions","questionCategories","scaleCategories")){Object raw=incoming.getOrDefault(kind,Collections.emptyList());if(kind.equals("scaleCategories")){clean.put(kind,raw);continue;}List<Map<String,Object>> values=list(raw);require(values.size()<=5000,422,"资料数量超出限制");Set<String> ids=new HashSet<>();for(Map<String,Object> v:values){String key=text(v,"id");require(key.matches("[A-Za-z0-9_-]{1,36}")&&ids.add(key),422,"资料编号重复或无效");Map<String,Object> original=originals.get(kind+":"+key);if(original!=null){v.clear();v.putAll(original);}else if(kind.equals("questions")){require(!text(v,"text").isEmpty()&&text(v,"text").length()<=1000,422,"请填写题目内容");canonicalQuestion(v,key);v.put("standard",false);}else if(kind.equals("scales")){require(!text(v,"name").isEmpty()&&!text(v,"source").isEmpty(),422,"请填写量表名称与来源");v.put("standard",false);v.put("scaleType","custom");validateBands(v);}else require(!text(v,"name").isEmpty()&&text(v,"name").length()<=40,422,"分类名称无效");}clean.put(kind,values);}
  // Standard source records remain complete even if an old browser omitted them.
  for(String kind:Arrays.asList("scales","questions")){List<Map<String,Object>> values=list(clean.get(kind));Set<String> ids=new HashSet<>();for(Map<String,Object>v:values)ids.add(text(v,"id"));for(Map<String,Object>v:list(protectedCatalog.get(kind)))if(!ids.contains(text(v,"id")))values.add(v);clean.put(kind,values);}
  for(Map<String,Object> p:list(incoming.get("plans"))){String pid=text(p,"id");require(pid.matches("[A-Za-z0-9_-]{1,36}"),422,"问卷编号无效");Map<String,Object> existing=db.one("SELECT * FROM a_questionnaires WHERE questionnaire_id=? AND scope_code=? AND data_mode=? FOR UPDATE",pid,a.scope,a.mode);if(existing!=null&&!"draft".equals(existing.get("questionnaire_status")))continue;String title=surveys.field(p,"name",120,true);Map<String,Object> frozen=build(a,p,clean,false);if(existing==null)db.insert("a_questionnaires",map("questionnaire_id",pid,"scope_code",a.scope,"data_mode",a.mode,"title",title,"category","psychological","audience",text(p,"audience").isEmpty()?"全体职工":text(p,"audience"),"document_json",ehr.encode(frozen),"created_by",a.user,"updated_by",a.user,"created_at",now(),"updated_at",now()));else db.exec("UPDATE a_questionnaires SET title=?,document_json=?,row_version=row_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE questionnaire_id=?",title,ehr.encode(frozen),a.user,pid);}
  db.exec("UPDATE a_questionnaire_center_state SET document_json=?,row_version=row_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE scope_code=? AND data_mode=?",ehr.encode(clean),a.user,a.scope,a.mode);ehr.audit(a,null,null,null,"questionnaire_center_saved","维护题库、量表与问卷草稿；标准题目及发布版本不覆盖");return surveys.finish(a,b,map("version",num(old.get("row_version"))+1));
 }
 void validateBands(Map<String,Object> s){double last=-1;for(Map<String,Object>b:list(s.get("riskBands"))){double min=Double.parseDouble(str(b.get("min"))),max=Double.parseDouble(str(b.get("max")));require(Double.isFinite(min)&&Double.isFinite(max)&&min>=0&&max>=min&&min>last,422,"评分区间重叠或无效");last=max;}}
 Map<String,Object> canonicalQuestion(Map<String,Object> q,String key){List<Object> options=new ArrayList<>();List<Map<String,Object>> given=list(q.get("optionItems"));if(given.isEmpty()){String[] labels=text(q,"options").split("；");for(int i=0;i<labels.length;i++)given.add(map("label",labels[i],"score",i));}double min=Double.MAX_VALUE,max=0;for(Map<String,Object>o:given){double n=Double.parseDouble(str(o.get("score")));min=Math.min(min,n);max=Math.max(max,n);}int i=0;for(Map<String,Object>o:given){double value=Double.parseDouble(str(o.get("score")));if(Boolean.TRUE.equals(q.get("reverse"))||"reverse".equals(q.get("scoring"))||"reverse".equals(q.get("scoringDirection")))value=min+max-value;options.add(map("id","o"+(i++),"label",o.containsKey("label")?o.get("label"):o.get("text"),"score",value));}String type=text(q,"type");if(type.isEmpty()||type.equals("likert"))type="single";return (Map<String,Object>)surveys.questions(Collections.singletonList(map("id",key,"type",type,"title",q.get("text"),"required",!Boolean.FALSE.equals(q.get("required")),"options",options))).get(0);}
 Map<String,Object> build(EhrActor actor,Map<String,Object> p,Map<String,Object> catalog,boolean publishing){List<Object> qs=new ArrayList<>(),scoring=new ArrayList<>();Set<String> ids=new HashSet<>();List<Map<String,Object>>groups=list(obj(p.get("wizard")).get("groups"));List<String> selected=new ArrayList<>();if(p.get("scales") instanceof List)for(Object n:(List<?>)p.get("scales"))selected.add(str(n));if(selected.isEmpty()&&!text(p,"scale").isEmpty())selected.add(text(p,"scale"));for(String name:selected){Map<String,Object>s=null;for(Map<String,Object>v:list(catalog.get("scales")))if(name.equals(v.get("name")))s=v;require(s!=null,422,"关联量表不存在");if(publishing)require(!Boolean.TRUE.equals(s.get("restricted"))&&"已启用".equals(s.get("status")),422,"量表尚未启用或未导入授权原版："+name);List<Object> groupQuestions=new ArrayList<>();for(Map<String,Object>q:list(catalog.get("questions")))if(name.equals(q.get("scale"))&&"启用".equals(q.get("status"))){String key=text(q,"id");if(ids.add(key)){Map<String,Object> cq=canonicalQuestion(q,key);qs.add(cq);groupQuestions.add(cq);}}
   if(publishing)require(!groupQuestions.isEmpty(),422,"量表没有可发布题目："+name);List<Object> bands=new ArrayList<>();int bi=0;for(Map<String,Object>b:list(s.get("riskBands"))){Map<String,Object>v=new LinkedHashMap<>(b);v.put("level",bi==0?"low":bi==1?"mild":bi==2?"medium":"high");bands.add(v);bi++;}scoring.add(map("name",name,"version",s.get("version"),"source",s.get("source"),"method",s.getOrDefault("scoringMethod","total"),"bands",bands,"questions",groupQuestions));}
  // Custom questions selected in the wizard retain their own frozen options, without invented clinical cutoffs.
  for(Map<String,Object> g:groups)if(!text(g,"id").startsWith("scale-"))for(Map<String,Object>q:list(g.get("questions"))){String key=text(q,"id");if(ids.add(key)){Map<String,Object>v=new LinkedHashMap<>(q);if(!v.containsKey("text"))v.put("text",v.get("title"));qs.add(canonicalQuestion(v,key));}}
  if(publishing)surveys.questions(qs);Map<String,Object> config=new LinkedHashMap<>(p);config.put("status","草稿");return new AssessmentRuleRuntime(db,ehr).attach(actor,"questionnaire",map("title",p.get("name"),"category","psychological","audience",p.getOrDefault("audience","全体职工"),"description",p.getOrDefault("notes",""),"scoringBasis","冻结量表版本按选项计分；不同量表独立解释，结果待专业审核","questions",qs,"scoringScales",scoring,"centerConfig",config));
 }
 @Transactional public Object publish(EhrActor a,String id,Map<String,Object>b){surveys.doctor(a);try{Map<String,Object> replay=surveys.receipt(a,"center-publish-"+id,b);if(replay.get("result_json")!=null)return ehr.decode(replay.get("result_json"));Map<String,Object> q=surveys.owned(a,id,true);Map<String,Object>doc=obj(ehr.decode(q.get("document_json"))),p=obj(doc.get("centerConfig")),cat=obj(ehr.decode(state(a,false).get("document_json")));require(!Boolean.TRUE.equals(p.get("anonymous")),422,"匿名问卷暂不支持个人干预闭环，请关闭匿名后发布");Map<String,Object>release=obj(obj(p.get("wizard")).get("release"));String start=text(release,"time");if(start.isEmpty())start=text(p,"time");String end=text(release,"endTime");if(end.isEmpty())end=text(p,"endTime");require(!end.isEmpty()&&LocalDateTime.parse(end).isAfter(LocalDateTime.now(ZoneId.of("Asia/Shanghai")))&&(!start.isEmpty()&&LocalDateTime.parse(end).isAfter(LocalDateTime.parse(start))),422,"请设置有效的测评开始和截止时间");Object ch=release.get("channels");if(ch instanceof List)for(Object c:(List<?>)ch)require(!Arrays.asList("sms","email").contains(str(c))&&!str(c).contains("短信")&&!str(c).contains("邮件"),422,"短信和邮件发送尚未配置，请选择系统内/H5发布");p.put("time",start);p.put("endTime",end);Map<String,Object>frozen=build(a,p,cat,true);db.exec("UPDATE a_questionnaires SET document_json=? WHERE questionnaire_id=?",ehr.encode(frozen),id);
   List<Map<String,Object>> people=db.all("SELECT r.record_id id,p.employee_no code,p.organization_name unit,p.team_name team"+ehr.baseSql(),a.scope,a.mode);Set<String> targets=new LinkedHashSet<>();List<?> explicit=b.get("records") instanceof List?(List<?>)b.get("records"):Collections.emptyList();String scope=text(release,"range");String custom=text(release,"people"),audience=text(p,"audience");for(Map<String,Object>r:people){boolean yes=explicit.contains(r.get("id"));if(explicit.isEmpty()){if(scope.contains("custom")||scope.contains("自定义"))yes=Arrays.asList(custom.split("[，,\\s]+" )).contains(str(r.get("code")));else if(scope.contains("unit")||scope.contains("部门")){Object units=release.get("units");yes=units instanceof List&&((List<?>)units).contains(r.get("unit"));}else yes=audience.contains("全体");}if(yes&&!Arrays.asList(text(release,"excluded").split("[，,\\s]+" )).contains(str(r.get("code"))))targets.add(str(r.get("id")));}require(explicit.isEmpty()||targets.size()==new HashSet<>(explicit).size(),403,"接收对象包含不可访问职工或已排除人员");require(!targets.isEmpty(),422,"请明确选择接收职工；不根据名称猜测新入职或井下人员");Object result=surveys.publish(a,map("requestKey",java.util.UUID.nameUUIDFromBytes(bytes(text(b,"requestKey")+":issue")).toString(),"ids",Arrays.asList(id),"versions",map(id,q.get("row_version")),"records",new ArrayList<>(targets),"dueDate",end.substring(0,10)));for(Map<String,Object>x:db.all("SELECT x.assignment_id FROM a_questionnaire_assignments x JOIN a_questionnaire_releases l ON l.release_id=x.release_id WHERE l.questionnaire_id=?",id)){if(db.count("SELECT COUNT(*) FROM a_questionnaire_deliveries WHERE assignment_id=? AND delivery_kind='issued'",x.get("assignment_id"))==0)db.insert("a_questionnaire_deliveries",map("delivery_id",id(),"assignment_id",x.get("assignment_id"),"scope_code",a.scope,"data_mode",a.mode,"delivery_kind","issued","delivery_state","in_app_available","created_at",now()));}return surveys.finish(a,b,result);
  }finally{}}
 public static void afterSubmission(EhrRepository db,EhrService ehr,EhrActor a,String response,Map<String,Object>doc,Map<String,Object>answers){if(!doc.containsKey("scoringScales"))return;Map<String,Object>scored=QuestionnaireScoring.score(doc,answers),p=(Map<String,Object>)doc.get("centerConfig");Map<String,Object>w=p.get("wizard") instanceof Map?(Map<String,Object>)p.get("wizard"):Collections.emptyMap(),settings=w.get("settings") instanceof Map?(Map<String,Object>)w.get("settings"):Collections.emptyMap();boolean ai=Boolean.TRUE.equals(p.get("aiEnabled"))&&!Boolean.FALSE.equals(settings.get("aiReport"));db.insert("a_questionnaire_processing",map("response_id",response,"scope_code",a.scope,"data_mode",a.mode,"score_json",ehr.encode(scored),"ai_state",ai?"queued":"disabled","alert_state",Boolean.TRUE.equals(scored.get("urgent"))?"urgent_review":!Boolean.FALSE.equals(settings.get("alerts"))&&QuestionnaireScoring.rank(str(scored.get("risk")))>=3?"review_required":"none","created_at",now(),"updated_at",now()));}
 public static void afterReview(EhrRepository db,EhrService ehr,EhrActor a,String response,String decision,String note){if(!"confirmed".equals(decision))return;Map<String,Object>r=db.one("SELECT f.*,x.record_id,l.document_json FROM a_questionnaire_processing f JOIN a_questionnaire_responses s ON s.response_id=f.response_id JOIN a_questionnaire_assignments x ON x.assignment_id=s.assignment_id JOIN a_questionnaire_releases l ON l.release_id=x.release_id WHERE f.response_id=? AND f.scope_code=? AND f.data_mode=? FOR UPDATE",response,a.scope,a.mode);if(r==null)return;Map<String,Object>score=(Map<String,Object>)ehr.decode(r.get("score_json")),doc=(Map<String,Object>)ehr.decode(r.get("document_json")),config=(Map<String,Object>)doc.get("centerConfig");Map<String,Object>wizard=config.get("wizard") instanceof Map?(Map<String,Object>)config.get("wizard"):Collections.emptyMap(),settings=wizard.get("settings") instanceof Map?(Map<String,Object>)wizard.get("settings"):Collections.emptyMap();boolean intervention=Boolean.TRUE.equals(settings.get("intervention"));if(intervention&&r.get("intervention_json")==null&&(Boolean.TRUE.equals(score.get("urgent"))||QuestionnaireScoring.rank(str(score.get("risk")))>=3)){db.exec("UPDATE a_questionnaire_processing SET intervention_json=?,row_version=row_version+1,updated_at=UTC_TIMESTAMP(6) WHERE response_id=?",ehr.encode(map("id",id(),"title","审核后心理支持及复测任务","note",note,"owner",a.user,"state","pending","createdAt",now())),response);}
  int index=0;for(Map<String,Object>scale:QuestionnaireScoring.rows(score.get("scales"))){String key=java.util.UUID.nameUUIDFromBytes(bytes(response+":"+index++)).toString();if(db.count("SELECT COUNT(*) FROM a_psych_measurements WHERE scope_code=? AND data_mode=? AND request_key=?",a.scope,a.mode,key)>0)continue;db.insert("a_psych_measurements",map("measurement_id",id(),"scope_code",a.scope,"data_mode",a.mode,"record_id",r.get("record_id"),"category","psychological","instrument",str(scale.get("name"))+" "+str(scale.get("version")),"total_score",scale.get("score"),"max_score",scale.get("maxScore"),"measured_at",now(),"result_note","来源答卷 "+response+"；医生审核意见："+note,"source_description","已审核问卷冻结版本，来源："+str(scale.get("source")),"recorded_by",a.user,"request_key",key,"payload_digest",hex(digest(bytes(ehr.encode(scale)))),"created_at",now()));}
 }
 @Transactional public Object operate(EhrActor a,String id,Map<String,Object>b){surveys.doctor(a);Map<String,Object> receipt=surveys.receipt(a,"response-operation-"+id,b);if(receipt.get("result_json")!=null)return ehr.decode(receipt.get("result_json"));Map<String,Object>r=db.one("SELECT f.*,s.assignment_id,s.review_state,x.record_id FROM a_questionnaire_processing f JOIN a_questionnaire_responses s ON s.response_id=f.response_id JOIN a_questionnaire_assignments x ON x.assignment_id=s.assignment_id WHERE f.response_id=? AND f.scope_code=? AND f.data_mode=? FOR UPDATE",id,a.scope,a.mode);require(r!=null,404,"答卷不存在或无权限");ehr.profile(a,str(r.get("record_id")),false);String action=text(b,"action"),note=surveys.field(b,"note",2000,false);if(action.equals("retry")){require(Arrays.asList("failed","disabled").contains(r.get("ai_state")),409,"分析已排队或完成");db.exec("UPDATE a_questionnaire_processing SET ai_state='queued',attempts=0,ai_error=NULL,updated_at=UTC_TIMESTAMP(6) WHERE response_id=?",id);}else if(action.equals("task")){require("confirmed".equals(r.get("review_state")),409,"请先完成医生审核后生成个人干预任务");require(!note.isEmpty(),422,"请填写干预安排");if(r.get("intervention_json")==null)db.exec("UPDATE a_questionnaire_processing SET intervention_json=?,updated_at=UTC_TIMESTAMP(6) WHERE response_id=?",ehr.encode(map("id",id(),"title","心理干预及复测跟踪","note",note,"owner",a.user,"state","pending","createdAt",now())),id);}else if(action.equals("archive")){require("confirmed".equals(r.get("review_state")),409,"待审核答卷不能归档");db.exec("UPDATE a_questionnaire_processing SET archived=1,updated_at=UTC_TIMESTAMP(6) WHERE response_id=?",id);}else if(action.equals("flag")){require(!note.isEmpty(),422,"请填写异常依据");db.exec("UPDATE a_questionnaire_processing SET alert_state='manual_review',updated_at=UTC_TIMESTAMP(6) WHERE response_id=?",id);}else if(action.equals("complete-task")){require(r.get("intervention_json")!=null&&!note.isEmpty(),422,"请填写任务完成与复测记录");Map<String,Object>task=obj(ehr.decode(r.get("intervention_json")));task.putAll(map("state","completed","completedAt",now(),"result",note));db.exec("UPDATE a_questionnaire_processing SET intervention_json=?,updated_at=UTC_TIMESTAMP(6) WHERE response_id=?",ehr.encode(task),id);}else throw new EhrException(422,"操作无效");db.exec("UPDATE a_questionnaire_processing SET row_version=row_version+1 WHERE response_id=?",id);ehr.audit(a,str(r.get("record_id")),null,null,"questionnaire_"+action,"答卷 "+id+"；"+note);return surveys.finish(a,b,map("id",id,"action",action));}
 @Transactional public Object remind(EhrActor a,String id,Map<String,Object>b){surveys.doctor(a);surveys.owned(a,id,true);Map<String,Object>receipt=surveys.receipt(a,"remind-"+id,b);if(receipt.get("result_json")!=null)return ehr.decode(receipt.get("result_json"));int count=0;for(Map<String,Object>x:db.all("SELECT x.assignment_id FROM a_questionnaire_assignments x JOIN a_questionnaire_releases l ON l.release_id=x.release_id LEFT JOIN a_questionnaire_responses s ON s.assignment_id=x.assignment_id WHERE l.questionnaire_id=? AND l.release_status='active' AND s.response_id IS NULL AND (x.due_date IS NULL OR x.due_date>=CURDATE())",id)){if(db.count("SELECT COUNT(*) FROM a_questionnaire_deliveries WHERE assignment_id=? AND delivery_kind='reminder' AND created_at>DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY)",x.get("assignment_id"))>0)continue;db.insert("a_questionnaire_deliveries",map("delivery_id",id(),"assignment_id",x.get("assignment_id"),"scope_code",a.scope,"data_mode",a.mode,"delivery_kind","reminder","delivery_state","in_app_available","created_at",now()));count++;}return surveys.finish(a,b,map("reminded",count,"channel","系统内问卷待办"));}
 @Transactional public Object batch(EhrActor a,Map<String,Object>b){surveys.doctor(a);Map<String,Object> receipt=surveys.receipt(a,"center-batch",b);if(receipt.get("result_json")!=null)return ehr.decode(receipt.get("result_json"));List<Map<String,Object>> items=list(b.get("items"));require(!items.isEmpty()&&items.size()<=100,422,"请选择1至100份答卷");Set<String> seen=new HashSet<>();String action=text(b,"action");require(Arrays.asList("review","flag","task","archive").contains(action),422,"批量操作无效");String note=surveys.field(b,"note",2000,true);for(Map<String,Object> item:items){String id=text(item,"id");require(seen.add(id),422,"答卷重复");Map<String,Object>r=db.one("SELECT s.row_version,s.review_state FROM a_questionnaire_responses s WHERE s.response_id=? AND s.scope_code=? AND s.data_mode=? FOR UPDATE",id,a.scope,a.mode);require(r!=null,404,"包含不可访问答卷");require(num(item.get("version"))==num(r.get("row_version")),409,"答卷已更新，请刷新后操作");}
 for(Map<String,Object> item:items){String id=text(item,"id"),key=UUID.nameUUIDFromBytes(bytes(text(b,"requestKey")+":"+id)).toString();if(action.equals("review"))surveys.review(a,id,map("requestKey",key,"version",item.get("version"),"decision",b.getOrDefault("decision","confirmed"),"riskLevel",item.get("riskLevel"),"note",note,"sourceVerified",b.get("sourceVerified")));else operate(a,id,map("requestKey",key,"action",action,"note",note));}return surveys.finish(a,b,map("count",items.size(),"action",action));
 }

}
